// === Tab: brush ===
class PaintStroke {
	constructor(x, y) {
		// self.init_size = random(20, 50);
		// this.c = c;

		this.min_size = 2;
		this.fall_off = 1.5;
		this.cool_down = 1;
		this.counter = 0;
		this.smoothing = 20;


		// this.size = random(5, 10);
		// this.pos = createVector(x, y);
		// this.p_pos = createVector(x, y);
		this.reset(x, y)

	}

	reset(x, y) {
		this.size = random(10, 15);
		this.pos = createVector(x, y);
		this.p_pos = createVector(x, y);
		this.offset = createVector(random(-40, 40), random(-40, 40));
		this.c = img.get(this.pos.x + this.offset.x, this.pos.y + this.offset.y);
	}

	show() {
		strokeWeight(this.size);
		stroke(this.c);

		var start_x =this.p_pos.x + this.offset.x;
		var start_y =this.p_pos.y + this.offset.y;

		var end_x =this.pos.x + this.offset.x;
		var end_y =this.pos.y + this.offset.y;

		line(start_x, start_y, end_x, end_y);
		// ellipse(self.pos.x, self.pos.y, self.size)
	}

	update(x, y) {
		var complete = false;

		var fall_off = map(p5.Vector.dist(this.pos, this.p_pos) * 0.5, 0, 10, 0, 5);
		var fall_off = this.fall_off;

		this.size -= fall_off;

		if(this.size < this.min_size) {
			complete = true;
		}

		this.p_pos.set(this.pos.x, this.pos.y);

		this.pos.x += (x - this.pos.x)/this.smoothing;
		this.pos.y += (y - this.pos.y)/this.smoothing;

		// self.pos.set(x, y);

		return complete
	}

	show_and_update(x, y){
		// console.log(this.counter);

		if(this.counter == this.cool_down) {
			this.show();
			var status = this.update(x, y);
			if(status){
				this.counter = 0;
			}
		}
		else {
			this.counter++;
			if(this.counter == this.cool_down) {
				this.reset(x, y);
			}
		}
	}
}

